begin;

create temp table phoenix_levels (
  title text, song_type text, step_type text, level smallint, phoenix_level smallint
) on commit drop;


select sc.id, gs.id, v.phoenix_level
from phoenix_levels v
join public.songs s on lower(s.title) = lower(v.title) and s.song_type = v.song_type::public.song_type
join public.stepcharts sc
  on sc.song_id = s.id and sc.step_type = v.step_type::public.step_type and sc.level = v.level
join public.game_series gs on gs.name = 'Phoenix'
on conflict (stepchart_id, series_id)
do update set level = excluded.level
where stepchart_levels.level is distinct from excluded.level;

delete from public.stepchart_levels sl
using public.game_series gs
where sl.series_id = gs.id and gs.name = 'Phoenix'
  and not exists (
    select 1
    from phoenix_levels v
    join public.songs s on lower(s.title) = lower(v.title) and s.song_type = v.song_type::public.song_type
    join public.stepcharts sc
      on sc.song_id = s.id and sc.step_type = v.step_type::public.step_type and sc.level = v.level
    where sc.id = sl.stepchart_id
  );

commit;
